<script setup lang="ts">
import type { TextEvidenceItem } from '../api/review'
import { ref } from 'vue'
import OcrEvidence from './OcrEvidence.vue'
defineProps<{ evidence: TextEvidenceItem[]; allowLocate?: boolean }>()
defineEmits<{ locate: [start: number, end: number] }>()
const expandedSources = ref<string[]>([])
</script>
<template><p class="muted">字面片段是当前参考范围内的复用证据；BERT仅对筛选后的部分窗口提供语义辅助，两者不合成抄袭比例。</p><el-empty v-if="!evidence.length" description="当前参考范围没有可展示的候选证据" /><section v-for="item in evidence" :key="item.evidenceId" class="evidence-card"><div class="section-heading"><strong>{{ item.sourceTitle }}</strong><el-tag :type="item.acceptedCandidate ? 'warning' : 'info'" effect="plain">{{ item.acceptedCandidate ? '符合字面证据条件' : '召回候选，未达字面条件' }}</el-tag></div><p class="muted">来源{{ item.sourceWorkId }} / 修订{{ item.sourceRevisionId }} · {{ item.sourceKind === 'IMAGE_OCR' ? '来源图片OCR文字' : '来源正文' }} · TF-IDF {{ item.tfidfScore.toFixed(4) }}</p><a v-if="item.sourceUrl" :href="item.sourceUrl" target="_blank" rel="noopener noreferrer">{{ item.sourceUrl }}</a><p v-else-if="item.sourceMetadata?.description">{{ item.sourceMetadata.description }}</p><p>匹配{{ item.literalSummary.matched_characters }}个字符 · 查询字面覆盖{{ (item.literalSummary.query_character_coverage * 100).toFixed(1) }}% · 最长片段{{ item.literalSummary.longest_match }}字</p><div v-for="(match, index) in item.matches" :key="`${item.evidenceId}-${index}`" class="match-block"><div class="match-pair"><div><span class="muted">本稿片段 [{{ match.queryStart }}, {{ match.queryEnd }})</span><p><mark>{{ match.queryText }}</mark></p></div><div><span class="muted">来源片段 [{{ match.sourceStart }}, {{ match.sourceEnd }})</span><p><mark>{{ match.sourceText }}</mark></p></div></div><el-button v-if="allowLocate" size="small" @click="$emit('locate', match.queryStart, match.queryEnd)">定位正文</el-button></div><el-collapse v-if="item.semanticWindows.length"><el-collapse-item title="BERT部分窗口语义辅助"><div v-for="(window, index) in item.semanticWindows" :key="index" class="semantic-window"><p>BERT分数 {{ window.score.toFixed(4) }} · 独立展示，不是全文覆盖率</p><div class="match-pair"><p>{{ window.queryText }}</p><p>{{ window.sourceText }}</p></div></div></el-collapse-item></el-collapse><el-collapse v-if="item.sourceKind === 'IMAGE_OCR' && item.sourceMetadata?.ocr && item.sourceMetadata.sourceFileId" v-model="expandedSources"><el-collapse-item :name="item.evidenceId" title="来源图片与OCR区域"><OcrEvidence v-if="expandedSources.includes(item.evidenceId)" :result="item.sourceMetadata.ocr" :file-id="item.sourceMetadata.sourceFileId" source /></el-collapse-item></el-collapse><small class="muted evidence-id">证据 {{ item.evidenceId }}</small></section></template>
